<script setup>
import { formatBytes, torrentProgress } from '../utils'
defineProps({ torrents: { type: Object, default: () => ({items:[],total:0,page:1,page_size:50}) }, state: String, sort: String, filter: String, loading: Boolean })
defineEmits(['state','sort','filter','page'])
</script>

<template>
  <section class="seed-panel">
    <header><div><h3>托管种子</h3><small>共 {{ torrents.total || 0 }} 个 · 保种时长按下载器实际做种时间计算</small></div><VBtnToggle :model-value="state" mandatory density="compact" @update:model-value="$emit('state',$event)"><VBtn value="active">活跃</VBtn><VBtn value="deleted">已删除</VBtn><VBtn value="all">全部</VBtn></VBtnToggle></header>
    <div class="seed-filters"><VSelect :model-value="filter" label="查看" density="compact" hide-details :items="[{title:'全部种子',value:'all'},{title:'已达保种 · 24h零上传',value:'zero_upload'},{title:'已满足最低保种',value:'min_seed_met'},{title:'下载需要处理',value:'download_issues'}]" @update:model-value="$emit('filter',$event)"/><VSelect :model-value="sort" label="排序" density="compact" hide-details :items="[{title:'最近添加',value:'newest'},{title:'单位容量收益最低优先',value:'yield'},{title:'体积最大优先',value:'size'},{title:'保种时间最长优先',value:'seed_time'}]" @update:model-value="$emit('sort',$event)"/></div>
    <VProgressLinear v-if="loading" indeterminate height="2" color="primary"/>
    <div class="seed-scroll"><table><thead><tr><th>种子 / 加入时间</th><th>体积</th><th>实际保种</th><th>24h 上传</th><th>累计上传</th><th>分享率</th><th>下载状态</th></tr></thead><tbody><tr v-for="item in torrents.items" :key="item.hash"><td><strong :title="item.title">{{ item.title || item.hash }}</strong><small>已加入 {{ Number(item.age_hours||0).toFixed(0) }} 小时</small></td><td>{{ formatBytes(item.size) }}</td><td><span :class="{met:item.min_seed_met}">{{ item.seeding_hours===null?'未知':`${item.seeding_hours}h` }}</span><small>{{ item.min_seed_met?'已满足':`最低 ${item.min_seed_hours||0}h` }}</small></td><td>{{ item.upload_coverage_hours_24h>0?formatBytes(item.upload_delta_24h):'待观测' }}<small v-if="!item.upload_window_observed_24h">观测 {{ Number(item.upload_coverage_hours_24h||0).toFixed(1) }}h</small></td><td>{{ formatBytes(item.uploaded) }}</td><td>{{ Number(item.ratio||0).toFixed(2) }}</td><td><VChip size="x-small" variant="tonal" :color="item.download_overdue?'warning':item.deleted?'secondary':item.completed?'success':'default'">{{ item.deleted?'已移除':item.download_overdue?'下载超时':item.download_health_label||(item.completed?'已完成':`${torrentProgress(item)}%`) }}</VChip></td></tr></tbody></table><p v-if="!torrents.items?.length" class="seed-empty">{{ loading?'正在读取种子…':'当前筛选下没有种子' }}</p></div>
    <VPagination v-if="torrents.total>torrents.page_size" :model-value="torrents.page" :length="Math.ceil(torrents.total/torrents.page_size)" @update:model-value="$emit('page',$event)"/>
  </section>
</template>

<style scoped>
.seed-panel{margin-top:16px;padding:16px;border:1px solid rgba(var(--v-border-color),var(--v-border-opacity));border-radius:14px}.seed-panel header{display:flex;align-items:center;justify-content:space-between;gap:12px}.seed-panel h3{margin:0}.seed-panel small{display:block;font-size:.73rem;color:rgba(var(--v-theme-on-surface),var(--v-medium-emphasis-opacity))}.seed-filters{display:flex;gap:12px;max-width:620px;margin:16px 0}.seed-scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-size:.8rem;white-space:nowrap}th,td{text-align:left;padding:12px 10px;border-bottom:1px solid rgba(var(--v-border-color),var(--v-border-opacity))}th{font-weight:500;color:rgba(var(--v-theme-on-surface),var(--v-medium-emphasis-opacity))}td:first-child{min-width:220px;max-width:380px}td strong{display:block;overflow:hidden;text-overflow:ellipsis;max-width:380px}.met{color:rgb(var(--v-theme-success))}.seed-empty{padding:28px;text-align:center;color:rgba(var(--v-theme-on-surface),var(--v-medium-emphasis-opacity))}@media(max-width:599px){.seed-panel header{align-items:flex-start;flex-direction:column}.seed-filters{flex-direction:column}td:first-child,td strong{max-width:240px}}
</style>
